// HoneyCloud n8n Cross-Correlation Engine
const attack  = $('Webhook — Attack Received').first().json;
const abuse   = $('AbuseIPDB Lookup').first().json?.data   || {};
const vt      = $('VirusTotal Lookup').first().json?.data?.attributes || {};

const ac       = abuse.abuseConfidenceScore || 0;
const reports  = abuse.totalReports        || 0;
const stats    = vt.last_analysis_stats    || {};
const mv       = stats.malicious           || 0;
const total_e  = (stats.malicious||0)+(stats.harmless||0)+(stats.undetected||0)+(stats.suspicious||0);
const ratio    = total_e > 0 ? Math.round(mv/total_e*100*10)/10 : 0;
const rep      = vt.reputation             || 0;
const ml_score = attack.risk_score         || 0;

// Score each source
let abuse_score = 0;
if (ac >= 90) abuse_score = 45;
else if (ac >= 75) abuse_score = 35;
else if (ac >= 50) abuse_score = 24;
else if (ac >= 25) abuse_score = 14;
else if (ac >= 5)  abuse_score = 6;
if (reports >= 500) abuse_score += 8;
else if (reports >= 100) abuse_score += 5;

let vt_score = 0;
if (mv >= 20 || ratio >= 30) vt_score = 40;
else if (mv >= 10 || ratio >= 15) vt_score = 30;
else if (mv >= 5  || ratio >= 7)  vt_score = 20;
else if (mv >= 2  || ratio >= 3)  vt_score = 10;
else if (mv >= 1)                 vt_score = 5;
if (rep <= -100) vt_score += 8;
else if (rep <= -50) vt_score += 5;

let ml_contrib = 0;
if (ml_score >= 85) ml_contrib = 10;
else if (ml_score >= 65) ml_contrib = 7;
else if (ml_score >= 40) ml_contrib = 4;

const primary = Math.max(abuse_score, vt_score);
const secondary = Math.min(abuse_score, vt_score);
const corroboration = (abuse_score >= 20 && vt_score >= 15) ? 8 : (abuse_score >= 10 && vt_score >= 10) ? 4 : 0;
const final_score = Math.min(primary + Math.floor(secondary/3) + ml_contrib + corroboration, 100);

let intel_level, action_taken, recommendation;
if (final_score >= 75) {
  intel_level = 'CONFIRMED_THREAT';
  action_taken = 'block_recommended';
  recommendation = 'Block at perimeter firewall immediately. Correlate with breach indicators.';
} else if (final_score >= 55) {
  intel_level = 'HIGH_CONFIDENCE';
  action_taken = 'watchlist_added';
  recommendation = 'Add to watchlist. Monitor for repeated attempts.';
} else if (final_score >= 30) {
  intel_level = 'SUSPICIOUS';
  action_taken = 'monitoring_increased';
  recommendation = 'Increase logging. Re-evaluate if activity continues.';
} else {
  intel_level = 'LOW_RISK';
  action_taken = 'logged';
  recommendation = 'No action required. Logging only.';
}

return [{
  json: {
    source_ip:            attack.source_ip,
    timestamp:            attack.timestamp,
    n8n_threat_score:     final_score,
    n8n_intel_level:      intel_level,
    n8n_recommendation:   recommendation,
    n8n_abuse_confidence: ac,
    n8n_vt_malicious:     mv,
    n8n_action_taken:     action_taken,
    n8n_workflow_id:      'honeycloud-v1',
    n8n_processed_at:     new Date().toISOString(),
    score_breakdown: {
      abuseipdb:      abuse_score,
      virustotal:     vt_score,
      ml_model:       ml_contrib,
      corroboration:  corroboration,
    }
  }
}];
